/**
 * Feature flags for the studio client.
 *
 * A flag is resolved once per read, highest precedence first:
 *
 *   1. `?flags=<name>:<value>`      — QA and demos without a rebuild
 *   2. `localStorage["studio.flags.<name>"]`
 *   3. the flag's build-time env variable
 *   4. the flag's declared default
 *
 * Unknown values fall through to the next source, so a typo in a query string
 * can never silently change behaviour.
 */

export type FeatureFlagName = "firstRunWizard";

export interface FeatureFlagDefinition {
  name: FeatureFlagName;
  description: string;
  envVar: string;
  defaultEnabled: boolean;
}

export const FEATURE_FLAGS: Record<FeatureFlagName, FeatureFlagDefinition> = {
  firstRunWizard: {
    name: "firstRunWizard",
    description: "Four-step welcome tour for first-time Living Studio users.",
    envVar: "VITE_STUDIO_FIRST_RUN_WIZARD",
    defaultEnabled: true,
  },
};

export const FLAG_STORAGE_PREFIX = "studio.flags.";
export const FLAG_QUERY_PARAM = "flags";

export type FlagSource = "query" | "storage" | "env" | "default";

export interface ResolvedFlag {
  enabled: boolean;
  source: FlagSource;
  raw: string | null;
}

export interface FlagSources {
  env?: string | null;
  stored?: string | null;
  query?: string | null;
}

const TRUTHY = new Set(["1", "true", "on", "yes", "enabled"]);
const FALSY = new Set(["0", "false", "off", "no", "disabled"]);

export function parseFlagValue(raw: string | null | undefined): boolean | null {
  if (raw === null || raw === undefined) {
    return null;
  }
  const normalized = raw.trim().toLowerCase();
  if (TRUTHY.has(normalized)) {
    return true;
  }
  if (FALSY.has(normalized)) {
    return false;
  }
  return null;
}

function readEnvFlag(definition: FeatureFlagDefinition): string | null {
  const env = import.meta.env as Record<string, unknown>;
  const raw = env[definition.envVar];
  if (raw === undefined || raw === null) {
    return null;
  }
  return String(raw);
}

function readStoredFlag(definition: FeatureFlagDefinition): string | null {
  if (typeof window === "undefined") {
    return null;
  }
  try {
    return window.localStorage.getItem(`${FLAG_STORAGE_PREFIX}${definition.name}`);
  } catch {
    // Private browsing modes can deny storage access.
    return null;
  }
}

/** `?flags=firstRunWizard:off,otherFlag:on` */
function readQueryFlag(definition: FeatureFlagDefinition): string | null {
  if (typeof window === "undefined") {
    return null;
  }
  const params = new URLSearchParams(window.location.search);
  for (const group of params.getAll(FLAG_QUERY_PARAM)) {
    for (const pair of group.split(",")) {
      const separator = pair.indexOf(":");
      if (separator === -1) {
        continue;
      }
      if (pair.slice(0, separator).trim() !== definition.name) {
        continue;
      }
      const value = pair.slice(separator + 1).trim();
      if (value) {
        return value;
      }
    }
  }
  return null;
}

function defaultSources(definition: FeatureFlagDefinition): Required<FlagSources> {
  return {
    query: readQueryFlag(definition),
    stored: readStoredFlag(definition),
    env: readEnvFlag(definition),
  };
}

export function resolveFlag(name: FeatureFlagName, sources?: FlagSources): ResolvedFlag {
  const definition = FEATURE_FLAGS[name];
  const resolved = sources ?? defaultSources(definition);

  const candidates: { source: FlagSource; raw: string | null | undefined }[] = [
    { source: "query", raw: resolved.query },
    { source: "storage", raw: resolved.stored },
    { source: "env", raw: resolved.env },
  ];

  for (const candidate of candidates) {
    const parsed = parseFlagValue(candidate.raw);
    if (parsed !== null) {
      return { enabled: parsed, source: candidate.source, raw: candidate.raw ?? null };
    }
  }

  return { enabled: definition.defaultEnabled, source: "default", raw: null };
}

export function isFeatureEnabled(name: FeatureFlagName, sources?: FlagSources): boolean {
  return resolveFlag(name, sources).enabled;
}

/** Persist a local override. Pass `null` to fall back to env/default. */
export function setFeatureOverride(name: FeatureFlagName, enabled: boolean | null): void {
  if (typeof window === "undefined") {
    return;
  }
  const key = `${FLAG_STORAGE_PREFIX}${name}`;
  try {
    if (enabled === null) {
      window.localStorage.removeItem(key);
      return;
    }
    window.localStorage.setItem(key, enabled ? "on" : "off");
  } catch {
    // Storage is an optimisation; the flag still resolves from env/default.
  }
}

export function clearFeatureOverride(name: FeatureFlagName): void {
  setFeatureOverride(name, null);
}

/**
 * The wire contract for agent-composed UI.
 *
 * A payload is a tree of `{ type, props, children }` nodes validated against a
 * catalog manifest. The manifest is plain JSON Schema (draft 2020-12 subset),
 * so the same document can be handed to the model as a tool schema and used
 * here to validate what comes back. Nothing is eval'd, no HTML is injected, and
 * every node is bounded before it can reach React.
 *
 * Parsing is deliberately forgiving where it is safe (unknown props are
 * stripped, unknown component types degrade to a visible fallback) and strict
 * where it matters (structure, required props, and size ceilings).
 */

export const UI_LIMITS = {
  maxDepth: 12,
  maxNodes: 200,
  maxStringLength: 2000,
  maxChildren: 32,
  maxActions: 40,
} as const;

/** A JSON Schema subset: enough to describe every prop in the catalog. */
export interface UiPropSchema {
  type?: "string" | "number" | "integer" | "boolean" | "array" | "object";
  description?: string;
  enum?: readonly string[];
  minimum?: number;
  maximum?: number;
  items?: UiPropSchema;
  properties?: Record<string, UiPropSchema>;
  required?: readonly string[];
  minItems?: number;
  maxItems?: number;
}

export interface UiCatalogEntry {
  type: string;
  kind: "layout" | "leaf";
  description: string;
  acceptsChildren: boolean;
  props: UiPropSchema;
}

export interface UiCatalogManifest {
  version: 1;
  components: UiCatalogEntry[];
}

export interface UiNode {
  type: string;
  props: Record<string, unknown>;
  children: UiNode[];
  /** Set when the manifest has no component for this type. */
  unsupported?: boolean;
}

export type ParseResult = { ok: true; node: UiNode } | { ok: false; reason: string };

type ValueResult = { ok: true; value: unknown } | { ok: false };

interface ParseState {
  entries: Map<string, UiCatalogEntry>;
  nodes: number;
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

export function catalogIndex(manifest: UiCatalogManifest): Map<string, UiCatalogEntry> {
  return new Map(manifest.components.map((entry) => [entry.type, entry]));
}

function ok(value: unknown): ValueResult {
  return { ok: true, value };
}

const INVALID: ValueResult = { ok: false };

function validateValue(raw: unknown, schema: UiPropSchema, depth: number): ValueResult {
  if (depth > UI_LIMITS.maxDepth + 4) {
    return INVALID;
  }

  if (schema.enum) {
    return typeof raw === "string" && schema.enum.includes(raw) ? ok(raw) : INVALID;
  }

  switch (schema.type) {
    case "string":
      if (typeof raw !== "string" || raw.length > UI_LIMITS.maxStringLength) {
        return INVALID;
      }
      return ok(raw);

    case "number":
    case "integer": {
      if (typeof raw !== "number" || !Number.isFinite(raw)) {
        return INVALID;
      }
      if (schema.type === "integer" && !Number.isInteger(raw)) {
        return INVALID;
      }
      if (schema.minimum !== undefined && raw < schema.minimum) {
        return INVALID;
      }
      if (schema.maximum !== undefined && raw > schema.maximum) {
        return INVALID;
      }
      return ok(raw);
    }

    case "boolean":
      return typeof raw === "boolean" ? ok(raw) : INVALID;

    case "array": {
      if (!Array.isArray(raw)) {
        return INVALID;
      }
      if (schema.minItems !== undefined && raw.length < schema.minItems) {
        return INVALID;
      }
      if (schema.maxItems !== undefined && raw.length > schema.maxItems) {
        return INVALID;
      }
      const items: unknown[] = [];
      for (const entry of raw) {
        const validated = schema.items ? validateValue(entry, schema.items, depth + 1) : ok(entry);
        if (!validated.ok) {
          return INVALID;
        }
        items.push(validated.value);
      }
      return ok(items);
    }

    case "object": {
      if (!isPlainObject(raw)) {
        return INVALID;
      }
      const result = validateProps(raw, schema, depth + 1);
      return result.ok ? ok(result.value) : INVALID;
    }

    default:
      return INVALID;
  }
}

function validateProps(
  raw: Record<string, unknown>,
  schema: UiPropSchema,
  depth: number,
): { ok: true; value: Record<string, unknown> } | { ok: false } {
  const properties = schema.properties ?? {};
  const result: Record<string, unknown> = {};

  for (const key of schema.required ?? []) {
    if (!(key in raw)) {
      return { ok: false };
    }
  }

  for (const [key, value] of Object.entries(raw)) {
    const propertySchema = properties[key];
    if (!propertySchema) {
      // Unknown props are stripped rather than trusted.
      continue;
    }
    const validated = validateValue(value, propertySchema, depth);
    if (!validated.ok) {
      if ((schema.required ?? []).includes(key)) {
        return { ok: false };
      }
      continue;
    }
    result[key] = validated.value;
  }

  return { ok: true, value: result };
}

function describePropFailure(entry: UiCatalogEntry, key: string): string {
  const schema = entry.props.properties?.[key];
  if (!schema) {
    return `unknown prop "${key}"`;
  }
  if (schema.enum) {
    return `prop "${key}" must be one of ${schema.enum.join(", ")}`;
  }
  if (schema.type === "number" || schema.type === "integer") {
    const bounds =
      schema.minimum !== undefined || schema.maximum !== undefined
        ? ` between ${schema.minimum ?? "-∞"} and ${schema.maximum ?? "∞"}`
        : "";
    return `prop "${key}" must be a ${schema.type}${bounds}`;
  }
  if (schema.type === "array") {
    return `prop "${key}" must be an array of valid items`;
  }
  if (schema.type === "object") {
    return `prop "${key}" must be an object with the documented fields`;
  }
  if (schema.type === "boolean") {
    return `prop "${key}" must be a boolean`;
  }
  return `prop "${key}" must be a ${schema.type ?? "valid value"}`;
}

function parseNode(raw: unknown, depth: number, state: ParseState): ParseResult {
  if (depth > UI_LIMITS.maxDepth) {
    return { ok: false, reason: `UI tree exceeds the maximum depth of ${UI_LIMITS.maxDepth}` };
  }
  state.nodes += 1;
  if (state.nodes > UI_LIMITS.maxNodes) {
    return { ok: false, reason: `UI tree exceeds the maximum of ${UI_LIMITS.maxNodes} nodes` };
  }

  if (!isPlainObject(raw)) {
    return { ok: false, reason: "UI node must be an object" };
  }

  const type = raw.type;
  if (typeof type !== "string" || type.trim() === "" || type.length > 100) {
    return { ok: false, reason: "UI node needs a component type" };
  }

  if (raw.props !== undefined && !isPlainObject(raw.props)) {
    return { ok: false, reason: `UI node "${type}" has non-object props` };
  }
  if (raw.children !== undefined && !Array.isArray(raw.children)) {
    return { ok: false, reason: `UI node "${type}" has non-array children` };
  }

  const entry = state.entries.get(type);
  if (!entry) {
    return { ok: true, node: { type, props: {}, children: [], unsupported: true } };
  }

/**
 * The closed catalog of surfaces the agent may compose.
 *
 * Two tiers, deliberately small: primitives for composition, cards for the ODI
 * shapes worth naming. Cards are leaves on the wire but render internally with
 * the same primitives, so the agent expresses intent ("score this outcome")
 * rather than layout.
 *
