import type {
  Conversation,
  ConversationTurn,
  Job,
  Observation,
  Outcome,
  Step,
} from "../../types";

export interface StoredJob extends Job {
  id: string;
  name: string;
  description: string;
  seq: number;
  created_at: string;
  updated_at: string;
}

export interface StoredStep extends Step {
  id: string;
  job_id: string;
  name: string;
  order: number;
  seq: number;
  created_at: string;
  updated_at: string;
}

export interface StoredOutcome extends Outcome {
  id: string;
  job_id: string;
  statement: string;
  importance: number | null;
  satisfaction: number | null;
  opportunity_score: number | null;
  seq: number;
  created_at: string;
  updated_at: string;
}

/**
 * The persistence boundary for local-first studio data.
 *
 * Implementations own ordering metadata (`seq`) so the service can mirror the
 * insertion order the Python repository guarantees without knowing whether the
 * bytes live in IndexedDB or a test-only Map.
 */
export interface LocalStore {
  readonly durable: boolean;
  nextSeq(): Promise<number>;
  listJobs(): Promise<StoredJob[]>;
  getJob(id: string): Promise<StoredJob | undefined>;
  putJob(job: StoredJob): Promise<void>;
  deleteJob(id: string): Promise<void>;
  listSteps(jobId?: string): Promise<StoredStep[]>;
  getStep(id: string): Promise<StoredStep | undefined>;
  putStep(step: StoredStep): Promise<void>;
  deleteStep(id: string): Promise<void>;
  listOutcomes(jobId?: string): Promise<StoredOutcome[]>;
  getOutcome(id: string): Promise<StoredOutcome | undefined>;
  putOutcome(outcome: StoredOutcome): Promise<void>;
  deleteOutcome(id: string): Promise<void>;
  listObservations(): Promise<Observation[]>;
  putObservation(observation: Observation): Promise<void>;
  deleteObservation(id: string): Promise<void>;
  clearObservations(): Promise<void>;
  listConversations(): Promise<Conversation[]>;
  getConversation(id: string): Promise<Conversation | undefined>;
  putConversation(conversation: Conversation): Promise<void>;
  listTurns(conversationId: string): Promise<ConversationTurn[]>;
  appendTurn(turn: Omit<ConversationTurn, "id">): Promise<ConversationTurn>;
  clearTurns(conversationId: string): Promise<void>;
  clearAll(): Promise<void>;
  close(): void;
}

export function bySeq<T extends { seq: number }>(left: T, right: T): number {
  return left.seq - right.seq;
}

import type {
  Conversation,
  ConversationTurn,
  Observation,
} from "../../types";
import {
  bySeq,
  type LocalStore,
  type StoredJob,
  type StoredOutcome,
  type StoredStep,
} from "./types";

/** Session-only fallback for browsers that deny IndexedDB. */
export class MemoryLocalStore implements LocalStore {
  readonly durable = false;
  private seq = 0;
  private turnId = 0;
  private readonly jobs = new Map<string, StoredJob>();
  private readonly steps = new Map<string, StoredStep>();
  private readonly outcomes = new Map<string, StoredOutcome>();
  private readonly observations = new Map<string, Observation>();
  private readonly conversations = new Map<string, Conversation>();
  private readonly turns: ConversationTurn[] = [];

  async nextSeq(): Promise<number> {
    this.seq += 1;
    return this.seq;
  }

  async listJobs(): Promise<StoredJob[]> {
    return [...this.jobs.values()].sort(bySeq);
  }

  async getJob(id: string): Promise<StoredJob | undefined> {
    return this.jobs.get(id);
  }

  async putJob(job: StoredJob): Promise<void> {
    this.jobs.set(job.id, job);
  }

  async deleteJob(id: string): Promise<void> {
    this.jobs.delete(id);
  }

  async listSteps(jobId?: string): Promise<StoredStep[]> {
    return [...this.steps.values()]
      .filter((step) => !jobId || step.job_id === jobId)
      .sort((left, right) => left.order - right.order || bySeq(left, right));
  }

  async getStep(id: string): Promise<StoredStep | undefined> {
    return this.steps.get(id);
  }

  async putStep(step: StoredStep): Promise<void> {
    this.steps.set(step.id, step);
  }

  async deleteStep(id: string): Promise<void> {
    this.steps.delete(id);
  }

  async listOutcomes(jobId?: string): Promise<StoredOutcome[]> {
    return [...this.outcomes.values()]
      .filter((outcome) => !jobId || outcome.job_id === jobId)
      .sort(bySeq);
  }

  async getOutcome(id: string): Promise<StoredOutcome | undefined> {
    return this.outcomes.get(id);
  }

  async putOutcome(outcome: StoredOutcome): Promise<void> {
    this.outcomes.set(outcome.id, outcome);
  }

  async deleteOutcome(id: string): Promise<void> {
    this.outcomes.delete(id);
  }

  async listObservations(): Promise<Observation[]> {
    return [...this.observations.values()].sort((left, right) =>
      left.created_at.localeCompare(right.created_at),
    );
  }

  async putObservation(observation: Observation): Promise<void> {
    this.observations.set(observation.id, observation);
  }

  async deleteObservation(id: string): Promise<void> {
    this.observations.delete(id);
  }

  async clearObservations(): Promise<void> {
    this.observations.clear();
  }

  async listConversations(): Promise<Conversation[]> {
    return [...this.conversations.values()].sort((left, right) =>
      right.updated_at.localeCompare(left.updated_at),
    );
  }

  async getConversation(id: string): Promise<Conversation | undefined> {
    return this.conversations.get(id);
  }

  async putConversation(conversation: Conversation): Promise<void> {
    this.conversations.set(conversation.id, conversation);
  }

  async listTurns(conversationId: string): Promise<ConversationTurn[]> {
    return this.turns
      .filter((turn) => turn.conversation_id === conversationId)
      .sort((left, right) => left.id - right.id);
  }

  async appendTurn(turn: Omit<ConversationTurn, "id">): Promise<ConversationTurn> {
    this.turnId += 1;
    const stored = { ...turn, id: this.turnId };
    this.turns.push(stored);
    return stored;
  }

  async clearTurns(conversationId: string): Promise<void> {
    for (let index = this.turns.length - 1; index >= 0; index -= 1) {
      if (this.turns[index].conversation_id === conversationId) {
        this.turns.splice(index, 1);
      }
    }
  }

  async clearAll(): Promise<void> {
    this.jobs.clear();
    this.steps.clear();
    this.outcomes.clear();
    this.observations.clear();
    this.conversations.clear();
    this.turns.length = 0;
    this.seq = 0;
    this.turnId = 0;
  }

  close(): void {
    /* nothing to release */
  }
}

import { openDB, type DBSchema, type IDBPDatabase } from "idb";

import type {
  Conversation,
  ConversationTurn,
  Observation,
} from "../../types";
import {
  bySeq,
  type LocalStore,
  type StoredJob,
  type StoredOutcome,
  type StoredStep,
} from "./types";

const DB_NAME = "agentic-odi-studio";
const DB_VERSION = 1;

interface StudioDb extends DBSchema {
  meta: { key: string; value: { key: string; value: number } };
  jobs: { key: string; value: StoredJob; indexes: { "by-seq": number } };
  steps: {
    key: string;
    value: StoredStep;
    indexes: { "by-job": string; "by-seq": number };
  };
  outcomes: {
    key: string;
    value: StoredOutcome;
    indexes: { "by-job": string; "by-seq": number };
  };
  observations: {
    key: string;
    value: Observation;
    indexes: { "by-created": string };
  };
  conversations: {
    key: string;
    value: Conversation;
    indexes: { "by-updated": string };
  };
  turns: {
    key: number;
    value: ConversationTurn;
    indexes: { "by-conversation": string };
  };
}

export class IndexedDbLocalStore implements LocalStore {
  readonly durable = true;
  private readonly db: IDBPDatabase<StudioDb>;

  private constructor(db: IDBPDatabase<StudioDb>) {
    this.db = db;
  }

  static async open(): Promise<IndexedDbLocalStore> {
    const db = await openDB<StudioDb>(DB_NAME, DB_VERSION, {
      upgrade(database) {
        database.createObjectStore("meta", { keyPath: "key" });
        const jobs = database.createObjectStore("jobs", { keyPath: "id" });
        jobs.createIndex("by-seq", "seq");
        const steps = database.createObjectStore("steps", { keyPath: "id" });
        steps.createIndex("by-job", "job_id");
        steps.createIndex("by-seq", "seq");
        const outcomes = database.createObjectStore("outcomes", { keyPath: "id" });
        outcomes.createIndex("by-job", "job_id");
        outcomes.createIndex("by-seq", "seq");
        const observations = database.createObjectStore("observations", {
          keyPath: "id",
        });
        observations.createIndex("by-created", "created_at");
        const conversations = database.createObjectStore("conversations", {
          keyPath: "id",
        });
        conversations.createIndex("by-updated", "updated_at");
        const turns = database.createObjectStore("turns", {
          keyPath: "id",
          autoIncrement: true,
        });
        turns.createIndex("by-conversation", "conversation_id");
      },
    });
    return new IndexedDbLocalStore(db);
  }

  async nextSeq(): Promise<number> {
    const tx = this.db.transaction("meta", "readwrite");
    const current = (await tx.store.get("seq"))?.value ?? 0;
    const next = current + 1;
    await tx.store.put({ key: "seq", value: next });
    await tx.done;
    return next;
  }

  async listJobs(): Promise<StoredJob[]> {
    const jobs = await this.db.getAll("jobs");
    return jobs.sort(bySeq);
  }

  async getJob(id: string): Promise<StoredJob | undefined> {
    return this.db.get("jobs", id);
  }

  async putJob(job: StoredJob): Promise<void> {
    await this.db.put("jobs", job);
  }

  async deleteJob(id: string): Promise<void> {
    await this.db.delete("jobs", id);
  }

  async listSteps(jobId?: string): Promise<StoredStep[]> {
    const steps = jobId
      ? await this.db.getAllFromIndex("steps", "by-job", jobId)
      : await this.db.getAll("steps");
    return steps.sort((left, right) => left.order - right.order || bySeq(left, right));
  }

  async getStep(id: string): Promise<StoredStep | undefined> {
    return this.db.get("steps", id);
  }

  async putStep(step: StoredStep): Promise<void> {
    await this.db.put("steps", step);
  }

  async deleteStep(id: string): Promise<void> {
    await this.db.delete("steps", id);
  }

  async listOutcomes(jobId?: string): Promise<StoredOutcome[]> {
    const outcomes = jobId
      ? await this.db.getAllFromIndex("outcomes", "by-job", jobId)
      : await this.db.getAll("outcomes");
    return outcomes.sort(bySeq);
  }

  async getOutcome(id: string): Promise<StoredOutcome | undefined> {
    return this.db.get("outcomes", id);
  }

  async putOutcome(outcome: StoredOutcome): Promise<void> {
    await this.db.put("outcomes", outcome);
  }

  async deleteOutcome(id: string): Promise<void> {
    await this.db.delete("outcomes", id);
  }

  async listObservations(): Promise<Observation[]> {
    const observations = await this.db.getAll("observations");
    return observations.sort((left, right) =>
      left.created_at.localeCompare(right.created_at),
    );
  }

  async putObservation(observation: Observation): Promise<void> {
    await this.db.put("observations", observation);
  }

  async deleteObservation(id: string): Promise<void> {
    await this.db.delete("observations", id);
  }

  async clearObservations(): Promise<void> {
    await this.db.clear("observations");
  }

  async listConversations(): Promise<Conversation[]> {
    const conversations = await this.db.getAll("conversations");
    return conversations.sort((left, right) =>
      right.updated_at.localeCompare(left.updated_at),
    );
  }

  async getConversation(id: string): Promise<Conversation | undefined> {
    return this.db.get("conversations", id);
  }

  async putConversation(conversation: Conversation): Promise<void> {
    await this.db.put("conversations", conversation);
  }

  async listTurns(conversationId: string): Promise<ConversationTurn[]> {
    return this.db.getAllFromIndex("turns", "by-conversation", conversationId);
  }

  async appendTurn(turn: Omit<ConversationTurn, "id">): Promise<ConversationTurn> {
    const id = await this.db.add("turns", turn as ConversationTurn);
    return { ...turn, id: Number(id) };
  }

  async clearTurns(conversationId: string): Promise<void> {
    const tx = this.db.transaction("turns", "readwrite");
    const keys = await tx.store.index("by-conversation").getAllKeys(conversationId);
    await Promise.all(keys.map((key) => tx.store.delete(key)));
    await tx.done;
  }

  async clearAll(): Promise<void> {
    const tx = this.db.transaction(
      [
        "meta",
        "jobs",
        "steps",
        "outcomes",
        "observations",
        "conversations",
        "turns",
      ],
      "readwrite",
    );
    await Promise.all([
      tx.objectStore("meta").clear(),
      tx.objectStore("jobs").clear(),
      tx.objectStore("steps").clear(),
      tx.objectStore("outcomes").clear(),
      tx.objectStore("observations").clear(),
      tx.objectStore("conversations").clear(),
      tx.objectStore("turns").clear(),
    ]);
    await tx.done;
  }

  close(): void {
    this.db.close();
  }
}

import { IndexedDbLocalStore } from "./indexedDbStore";
import { MemoryLocalStore } from "./memoryStore";
import type { LocalStore } from "./types";

export async function openLocalStore(): Promise<LocalStore> {
  if (typeof indexedDB === "undefined") {
    return new MemoryLocalStore();
  }
  try {
    return await IndexedDbLocalStore.open();
  } catch {
    // Private browsing and hardened WebViews can deny IndexedDB. The studio
    // still works for the session, and the capability manifest says so.
    return new MemoryLocalStore();
  }
}

import type { StudioError } from "../types";

/** A local BFF failure carrying the same shape the sidecar uses. */
export class BffError extends Error {
  readonly studioError: StudioError;

  constructor(
    code: string,
    message: string,
    options: {
      detail?: string | null;
      suggestion?: string | null;
      retryable?: boolean;
    } = {},
  ) {
    super(message);
    this.name = "BffError";
    this.studioError = {
      code,
      message,
      detail: options.detail ?? null,
      suggestion: options.suggestion ?? null,
      retryable: options.retryable ?? false,
    };
  }
}

export function notFound(entity: string, id: string): BffError {
  return new BffError("not_found", `${entity} ${id} was not found.`, {
    suggestion: "Refresh the canvas and try again.",
  });
}

export function validation(message: string): BffError {
  return new BffError("validation", message, {
    suggestion: "Check the value and try again.",
  });
}

