import type {
  Conversation,
  ConversationTurn,
  LatestConversation,
  Observation,
  ObservationKind,
  ObservationStatus,
} from "../../types";
import { notFound, validation } from "../errors";
import { newId, nowIso } from "../id";
import type { LocalStore } from "../store/types";

const OBSERVATION_KINDS = new Set<ObservationKind>([
  "career",
  "opportunity",
  "business",
  "stakeholder",
  "constraint",
  "evidence",
  "preference",
]);
const OBSERVATION_STATUSES = new Set<ObservationStatus>([
  "suggested",
  "confirmed",
  "dismissed",
]);
const TURN_ROLES = new Set<ConversationTurn["role"]>([
  "user",
  "assistant",
  "system",
  "tool",
]);
const MAX_TEXT = 2000;
const MAX_CONTEXT_TEXT = 500;
const MAX_CONTEXT_CHARS = 4000;
const MAX_SUGGESTED_IN_CONTEXT = 10;

function cleanText(text: string): string {
  const cleaned = text.trim();
  if (!cleaned) {
    throw validation("Observation text cannot be empty.");
  }
  if (cleaned.length > MAX_TEXT) {
    throw validation(`Observation text cannot exceed ${MAX_TEXT} characters.`);
  }
  return cleaned;
}

function cleanKind(kind: string): ObservationKind {
  if (!OBSERVATION_KINDS.has(kind as ObservationKind)) {
    throw validation(`Unknown observation kind: ${kind}.`);
  }
  return kind as ObservationKind;
}

function cleanStatus(status: string): ObservationStatus {
  if (!OBSERVATION_STATUSES.has(status as ObservationStatus)) {
    throw validation(`Unknown observation status: ${status}.`);
  }
  return status as ObservationStatus;
}

function cleanConfidence(confidence: number): number {
  if (!Number.isFinite(confidence) || confidence < 0 || confidence > 1) {
    throw validation("Confidence must be between 0 and 1.");
  }
  return confidence;
}

function cleanData(data: Record<string, unknown> | undefined): Record<string, unknown> {
  return data ?? {};
}

export class LocalMemoryService {
  constructor(private readonly store: LocalStore) {}

  async listObservations(includeDismissed = false): Promise<Observation[]> {
    const observations = await this.store.listObservations();
    return includeDismissed
      ? observations
      : observations.filter((observation) => observation.status !== "dismissed");
  }

  async addObservation(input: {
    kind: string;
    text: string;
    data?: Record<string, unknown>;
    confidence?: number;
    confirmed?: boolean;
  }): Promise<Observation> {
    const now = nowIso();
    const observation: Observation = {
      id: newId(),
      kind: cleanKind(input.kind),
      text: cleanText(input.text),
      data: cleanData(input.data),
      status: input.confirmed ? "confirmed" : "suggested",
      confidence: cleanConfidence(input.confidence ?? 0.5),
      source_turn: null,
      created_at: now,
      updated_at: now,
    };
    await this.store.putObservation(observation);
    return observation;
  }

  async updateObservation(
    observationId: string,
    input: {
      text?: string;
      status?: string;
      data?: Record<string, unknown>;
      confidence?: number;
    },
  ): Promise<Observation> {
    const existing = (await this.store.listObservations()).find(
      (observation) => observation.id === observationId,
    );
    if (!existing) {
      throw notFound("Observation", observationId);
    }
    const next: Observation = {
      ...existing,
      text: input.text === undefined ? existing.text : cleanText(input.text),
      status:
        input.status === undefined ? existing.status : cleanStatus(input.status),
      data: input.data === undefined ? existing.data : cleanData(input.data),
      confidence:
        input.confidence === undefined
          ? existing.confidence
          : cleanConfidence(input.confidence),
      updated_at: nowIso(),
    };
    await this.store.putObservation(next);
    return next;
  }

  async deleteObservation(observationId: string): Promise<{ ok: boolean }> {
    const exists = (await this.store.listObservations()).some(
      (observation) => observation.id === observationId,
    );
    if (!exists) {
      throw notFound("Observation", observationId);
    }
    await this.store.deleteObservation(observationId);
    return { ok: true };
  }

  async clearMemory(): Promise<{ ok: boolean }> {
    await this.store.clearObservations();
    const conversations = await this.store.listConversations();
    for (const conversation of conversations) {
      await this.store.clearTurns(conversation.id);
    }
    return { ok: true };
  }

  async createConversation(title = ""): Promise<Conversation> {
    const now = nowIso();
    const conversation: Conversation = {
      id: newId(),
      title: title.trim(),
      created_at: now,
      updated_at: now,
    };
    await this.store.putConversation(conversation);
    return conversation;
  }

  async latestConversation(): Promise<LatestConversation> {
    const conversations = await this.store.listConversations();
    const conversation = conversations[0] ?? null;
    if (!conversation) {
      return { conversation: null, turns: [] };
    }
    return {
      conversation,
      turns: await this.store.listTurns(conversation.id),
    };
  }

  async listTurns(conversationId: string): Promise<ConversationTurn[]> {
    if (!(await this.store.getConversation(conversationId))) {
      throw notFound("Conversation", conversationId);
    }
    return this.store.listTurns(conversationId);
  }

  async appendTurn(
    conversationId: string,
    role: ConversationTurn["role"],
    content: string,
  ): Promise<ConversationTurn> {
    if (!TURN_ROLES.has(role)) {
      throw validation(`Unknown turn role: ${role}.`);
    }
    const conversation = await this.store.getConversation(conversationId);
    if (!conversation) {
      throw notFound("Conversation", conversationId);
    }
    const turn = await this.store.appendTurn({
      conversation_id: conversationId,
      role,
      content,
      created_at: nowIso(),
    });
    const now = nowIso();
    await this.store.putConversation({
      ...conversation,
      title:
        role === "user" && content.trim() && !conversation.title
          ? content.trim().slice(0, 80)
          : conversation.title,
      updated_at: now,
    });
    return turn;
  }

  async memoryContext(): Promise<string> {
    const observations = (await this.listObservations()).filter(
      (observation) => observation.status === "confirmed",
    );
    const suggested = (await this.listObservations()).filter(
      (observation) => observation.status === "suggested",
    );
    const lines: string[] = [];
    let length = 0;
    const add = (line: string): void => {
      if (length + line.length > MAX_CONTEXT_CHARS) {
        return;
      }
      lines.push(line);
      length += line.length + 1;
    };
    if (observations.length) {
      add("Confirmed context:");
      for (const observation of observations) {
        add(`- [${observation.kind}] ${observation.text.slice(0, MAX_CONTEXT_TEXT)}`);
      }
    }
    if (suggested.length) {
      add("Suggested context (not yet confirmed):");
      for (const observation of suggested.slice(0, MAX_SUGGESTED_IN_CONTEXT)) {
        add(`- [${observation.kind}] ${observation.text.slice(0, MAX_CONTEXT_TEXT)}`);
      }
    }
    return lines.join("\n");
  }
}

import type { StudioConfig } from "../../types";

export type CapabilityId =
  | "local-data"
  | "local-memory"
  | "deterministic-assistant"
  | "browser-model"
  | "endpoint-model"
  | "sidecar-llm"
  | "sidecar-connectors"
  | "sidecar-mcp"
  | "sidecar-import";

export interface Capability {
  id: CapabilityId;
  label: string;
  description: string;
  status: "available" | "unavailable";
  reason?: string;
}

export interface CapabilityProbe {
  id: CapabilityId;
  label: string;
  description: string;
  check(settings: StudioConfig): Promise<boolean>;
}

const localStatuses: Record<CapabilityId, Capability> = {
  "local-data": {
    id: "local-data",
    label: "Local canvas data",
    description: "Jobs, steps, and outcomes stored in your browser.",
    status: "available",
  },
  "local-memory": {
    id: "local-memory",
    label: "Local memory and conversations",
    description: "Observations, conversation history, and context stored locally.",
    status: "available",
  },
  "deterministic-assistant": {
    id: "deterministic-assistant",
    label: "Deterministic assistant",
    description: "Answers about your canvas and updates it without a model.",
    status: "available",
  },
  "browser-model": {
    id: "browser-model",
    label: "Browser built-in model",
    description: "Uses the browser's built-in large language model when present.",
    status: "unavailable",
  },
  "endpoint-model": {
    id: "endpoint-model",
    label: "Configured model endpoint",
    description: "Calls the model endpoint you configured in Settings directly.",
    status: "unavailable",
  },
  "sidecar-llm": {
    id: "sidecar-llm",
    label: "Sidecar model proxy",
    description: "Streams model responses through the local Python sidecar.",
    status: "unavailable",
  },
  "sidecar-connectors": {
    id: "sidecar-connectors",
    label: "Sidecar connectors",
    description: "Adds third-party data sources through the sidecar.",
    status: "unavailable",
  },
  "sidecar-mcp": {
    id: "sidecar-mcp",
    label: "Sidecar MCP",
    description: "Runs MCP servers through the sidecar.",
    status: "unavailable",
  },
  "sidecar-import": {
    id: "sidecar-import",
    label: "Sidecar import",
    description: "Imports canvas data and memory from a reachable sidecar.",
    status: "unavailable",
  },
};

function isBrowserModelAvailable(): boolean {
  const ai = (globalThis as { ai?: { languageModel?: unknown } }).ai;
  return Boolean(ai && typeof ai.languageModel === "function");
}

function isEndpointConfigured(settings: StudioConfig): boolean {
  return Boolean(
    settings.base_url &&
      settings.api_key &&
      settings.model_name &&
      settings.base_url !== "http://localhost:8001/v1",
  );
}

export class CapabilityRegistry {
  private readonly probes: CapabilityProbe[] = [
    {
      id: "browser-model",
      label: localStatuses["browser-model"].label,
      description: localStatuses["browser-model"].description,
      check: async () => isBrowserModelAvailable(),
    },
    {
      id: "endpoint-model",
      label: localStatuses["endpoint-model"].label,
      description: localStatuses["endpoint-model"].description,
      check: async (settings) => isEndpointConfigured(settings),
    },
    {
      id: "sidecar-llm",
      label: localStatuses["sidecar-llm"].label,
      description: localStatuses["sidecar-llm"].description,
      check: async (settings) => this.probeSidecar(settings.base_url, "/api/capabilities"),
    },
    {
      id: "sidecar-connectors",
      label: localStatuses["sidecar-connectors"].label,
      description: localStatuses["sidecar-connectors"].description,
      check: async (settings) => this.probeSidecar(settings.base_url, "/api/connectors"),
    },
    {
      id: "sidecar-mcp",
      label: localStatuses["sidecar-mcp"].label,
      description: localStatuses["sidecar-mcp"].description,
      check: async (settings) => this.probeSidecar(settings.base_url, "/api/health/mcp"),
    },
    {
      id: "sidecar-import",
      label: localStatuses["sidecar-import"].label,
      description: localStatuses["sidecar-import"].description,
      check: async (settings) => this.probeSidecar(settings.base_url, "/api/capabilities"),
    },
  ];

  async statuses(settings: StudioConfig): Promise<Capability[]> {
    const results = await Promise.all(
      this.probes.map(async (probe) => {
        let ok = false;
        let reason: string | undefined;
        try {
          ok = await probe.check(settings);
        } catch (error) {
          ok = false;
          reason = error instanceof Error ? error.message : "Probe failed.";
        }
        return {
          ...localStatuses[probe.id],
          status: ok ? "available" : "unavailable",
          ...(ok ? {} : { reason }),
        };
      }),
    );
    return [
      localStatuses["local-data"],
      localStatuses["local-memory"],
      localStatuses["deterministic-assistant"],
      ...results,
    ];
  }

  private async probeSidecar(baseUrl: string, path: string): Promise<boolean> {
    try {
      const response = await fetch(`${baseUrl.replace(/\/$/, "")}${path}`, {
        signal: AbortSignal.timeout(2000),
      });
      return response.ok;
    } catch {
      return false;
    }
  }
}

export const capabilityRegistry = new CapabilityRegistry();

import type { CanvasData } from "../../types";
import type { LocalStore } from "../store/types";
import { openLocalStore } from "../store/openStore";
import { LocalDataService } from "../data/localDataService";
import { LocalMemoryService } from "../memory/localMemoryService";
import { ChatOrchestrator } from "../chat/orchestrator";
import { CapabilityRegistry, capabilityRegistry } from "../capabilities/registry";

export class StudioBff {
  readonly store: LocalStore;
  readonly data: LocalDataService;
  readonly memory: LocalMemoryService;
  readonly chat: ChatOrchestrator;
  readonly capabilities: CapabilityRegistry;

  constructor(store: LocalStore) {
    this.store = store;
    this.data = new LocalDataService(store);
    this.memory = new LocalMemoryService(store);
    this.chat = new ChatOrchestrator(store, this.data, this.memory);
    this.capabilities = capabilityRegistry;
  }

  async init(): Promise<void> {
    // Forces the store to open eagerly so later calls are not awaiting open.
    await this.store.nextSeq().catch(() => undefined);
  }

  async fetchCanvas(): Promise<CanvasData> {
    return this.data.fetchCanvas();
  }
}

let studioBffPromise: Promise<StudioBff> | null = null;

export async function getStudioBff(): Promise<StudioBff> {
  if (!studioBffPromise) {
    studioBffPromise = (async () => {
      const store = await openLocalStore();
      const bff = new StudioBff(store);
      await bff.init();
      return bff;
    })();
  }
  return studioBffPromise;
}

export async function resetStudioBffForTests(): Promise<void> {
  const current = studioBffPromise;
  studioBffPromise = null;
  if (current) {
    try {
      (await current).store.close();
    } catch {
      /* ignore */
    }
  }
}

