function isEndpointConfigured(request: {
  base_url: string;
  api_key: string;
  model: string;
}): boolean {
  return Boolean(
    request.base_url &&
      request.api_key &&
      request.model &&
      request.base_url !== "http://localhost:8001/v1",
  );
}

