  sidecar: () => Promise<T>,
  local: (bff: Awaited<ReturnType<typeof getStudioBff>>) => Promise<T>,
): Promise<T> {
  try {
    return await sidecar();
  } catch {
    const bff = await getStudioBff();
    return local(bff);
  }
}

